import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<String> buah = new ArrayList<>();
        buah.add("semangka");
        buah.add("kiwi");
        buah.add("jeruk");
        buah.add("mangga");

        // Cara lama: anonymous class
        Collections.sort(buah, new Comparator<String>() {
            @Override
            public int compare(String a, String b) {
                return a.length() - b.length();
            }
        });
        System.out.println(buah);

        // Cara baru: lambda
        Collections.sort(buah, (a, b) -> a.compareTo(b));
        System.out.println(buah);

        Sapa ramah = nama -> "Halo, " + nama + "!";
        System.out.println(ramah.sapa("Rina"));
    }
}

interface Sapa {
    String sapa(String nama);
}

